import{r as t}from"./request-DXDGNvfH.js";const s=e=>encodeURIComponent(String(e||"")),i={getList(e){return t.get("/mails",{params:e})},getDetail(e){return t.get(`/mails/${s(e)}`)},saveDraft(e,r){return t.post(`/mails/${s(e)}/save`,{body:r})},approve(e){return t.post(`/mails/${s(e)}/approve`)},reject(e,r){return t.post(`/mails/${s(e)}/reject`,{reason:r})},delete(e){return t.post("/mails/delete",{message_ids:e})},getStats(){return t.get("/mails/stats")}};export{i as m};
